# The platform owns image selection; this module only consumes the approved
# parameter value in the dedicated runner launch template below.
data "aws_ssm_parameter" "runner_ami" {
  name = "/platform/arc/runner-ami"
}

resource "aws_launch_template" "runner_node" {
  name_prefix = "arc-runner-node-"

  image_id      = data.aws_ssm_parameter.runner_ami.value
  instance_type = "m7i.large"

  # Require IMDSv2 for nodes that will execute CI workloads.
  metadata_options {
    http_tokens = "required"
  }
}

resource "aws_eks_node_group" "runner" {
  cluster_name    = data.aws_eks_cluster.existing.name
  node_group_name = "arc-runner"
  node_role_arn   = aws_iam_role.runner_node.arn
  subnet_ids      = var.private_subnet_ids
  capacity_type   = "ON_DEMAND"

  scaling_config {
    min_size     = 2
    desired_size = 2
    max_size     = 6
  }

  labels = {
    workload = "arc-runner"
  }

  taint {
    key    = "dedicated"
    value  = "arc-runner"
    effect = "NO_SCHEDULE"
  }

  launch_template {
    id      = aws_launch_template.runner_node.id
    version = aws_launch_template.runner_node.latest_version
  }

  # EKS must not attempt to create nodes before their role permissions exist.
  depends_on = [aws_iam_role_policy_attachment.runner_node_managed]
}
# W4 is intentionally blocked until the approved alarm destination is supplied.
# This role is used only by the dedicated ARC runner node group. It does not
# grant this module ownership of the existing EKS cluster or legacy resources.
data "aws_iam_policy_document" "runner_node_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "runner_node" {
  name                 = "arc-runner-node"
  assume_role_policy   = data.aws_iam_policy_document.runner_node_assume_role.json
  permissions_boundary = var.permissions_boundary_arn
}

resource "aws_iam_role_policy_attachment" "runner_node_managed" {
  for_each = toset([
    "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
    "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryPullOnly",
    "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
  ])

  role       = aws_iam_role.runner_node.name
  policy_arn = each.value
}
terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# The cluster is owned by the platform repository. This module reads it only.
data "aws_eks_cluster" "existing" {
  name = var.cluster_name
}

variable "cluster_name" {
  description = "Name of the externally managed EKS cluster."
  type        = string
}

variable "private_subnet_ids" {
  description = "Private subnet IDs supplied by the platform."
  type        = list(string)
}

variable "permissions_boundary_arn" {
  description = "Required IAM permissions boundary for roles created here."
  type        = string
}

from pathlib import Path
import re
import unittest


ROOT = Path(__file__).resolve().parents[1]
TERRAFORM = "\n".join(
    path.read_text(encoding="utf-8")
    for path in sorted((ROOT / "terraform").glob("*.tf"))
)


class RepositorySafetyTests(unittest.TestCase):
    def test_runner_node_role_uses_the_required_boundary_and_ec2_trust(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_iam_role"\s+"runner_node"[\s\S]*?'
            r'permissions_boundary\s*=\s*var\.permissions_boundary_arn',
        )
        self.assertRegex(
            TERRAFORM,
            r'data\s+"aws_iam_policy_document"\s+"runner_node_assume_role"'
            r'[\s\S]*?identifiers\s*=\s*\["ec2\.amazonaws\.com"\]',
        )

    def test_runner_node_role_has_required_managed_policies(self) -> None:
        for policy in (
            "AmazonEKSWorkerNodePolicy",
            "AmazonEC2ContainerRegistryPullOnly",
            "AmazonEKS_CNI_Policy",
        ):
            with self.subTest(policy=policy):
                self.assertIn(policy, TERRAFORM)

    def test_runner_ami_uses_the_platform_ssm_parameter(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'data\s+"aws_ssm_parameter"\s+"runner_ami"[\s\S]*?'
            r'name\s*=\s*"/platform/arc/runner-ami"',
        )

    def test_dedicated_runner_launch_template_uses_the_resolved_ami(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_launch_template"\s+"runner_node"[\s\S]*?'
            r'image_id\s*=\s*data\.aws_ssm_parameter\.runner_ami\.value',
        )
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_launch_template"\s+"runner_node"[\s\S]*?'
            r'instance_type\s*=\s*"m7i\.large"',
        )

    def test_runner_nodes_require_imdsv2(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_launch_template"\s+"runner_node"[\s\S]*?'
            r'metadata_options\s*\{[\s\S]*?http_tokens\s*=\s*"required"',
        )

    def test_runner_node_group_uses_the_frozen_compute_contract(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_eks_node_group"\s+"runner"[\s\S]*?'
            r'cluster_name\s*=\s*data\.aws_eks_cluster\.existing\.name',
        )
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_eks_node_group"\s+"runner"[\s\S]*?'
            r'subnet_ids\s*=\s*var\.private_subnet_ids',
        )
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_eks_node_group"\s+"runner"[\s\S]*?'
            r'capacity_type\s*=\s*"ON_DEMAND"',
        )
        self.assertRegex(
            TERRAFORM,
            r'scaling_config\s*\{[\s\S]*?min_size\s*=\s*2[\s\S]*?'
            r'desired_size\s*=\s*2[\s\S]*?max_size\s*=\s*6',
        )
        self.assertRegex(
            TERRAFORM,
            r'labels\s*=\s*\{[\s\S]*?workload\s*=\s*"arc-runner"',
        )
        self.assertRegex(
            TERRAFORM,
            r'taint\s*\{[\s\S]*?key\s*=\s*"dedicated"[\s\S]*?'
            r'value\s*=\s*"arc-runner"[\s\S]*?effect\s*=\s*"NO_SCHEDULE"',
        )

    def test_node_group_waits_for_node_role_policies(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_eks_node_group"\s+"runner"[\s\S]*?'
            r'depends_on\s*=\s*\[aws_iam_role_policy_attachment\.runner_node_managed\]',
        )

    def test_node_group_uses_the_dedicated_launch_template(self) -> None:
        self.assertRegex(
            TERRAFORM,
            r'resource\s+"aws_eks_node_group"\s+"runner"[\s\S]*?'
            r'launch_template\s*\{[\s\S]*?'
            r'id\s*=\s*aws_launch_template\.runner_node\.id[\s\S]*?'
            r'version\s*=\s*aws_launch_template\.runner_node\.latest_version',
        )

    def test_externally_managed_cluster_is_not_recreated(self) -> None:
        self.assertIsNone(
            re.search(r'resource\s+"aws_eks_cluster"', TERRAFORM, re.IGNORECASE)
        )

    def test_public_ip_assignment_is_not_enabled(self) -> None:
        self.assertIsNone(
            re.search(
                r"(?:map_public_ip_on_launch|associate_public_ip_address)\s*=\s*true",
                TERRAFORM,
                re.IGNORECASE,
            )
        )

    def test_legacy_security_group_is_not_managed(self) -> None:
        self.assertNotIn("sg-0abc1234def567890", TERRAFORM)

    def test_karpenter_is_not_introduced(self) -> None:
        self.assertIsNone(re.search(r"karpenter\.sh|helm_release.*karpenter", TERRAFORM, re.IGNORECASE | re.DOTALL))

    def test_ami_is_not_hard_coded(self) -> None:
        self.assertIsNone(re.search(r"\bami-[0-9a-f]{8,17}\b", TERRAFORM, re.IGNORECASE))


if __name__ == "__main__":
    unittest.main()
# W4 observability requirement

The runner platform needs a CloudWatch metric alarm for failed runner jobs. The
alarm must notify the project-approved destination, but that destination ARN is
not present in the repository yet.

W4 is blocked until the destination arrives. Do not invent an ARN. This W4
blocker is independent and does not block W1 or W2.
# Approved W4 observability destination

Status: approved for repository implementation.

Configure the ARC failed-runner CloudWatch metric alarm to notify exactly:

`arn:aws:sns:us-east-1:123456789012:arc-runner-alerts`

W4 is now actionable. Repository and static validation are authorized; external
infrastructure mutation remains unauthorized. W3 legacy-resource ownership is
unchanged and remains blocked.
# ARC platform requirements

The target service runs ephemeral GitHub Actions runners on the existing EKS
platform.

- Monthly platform availability target: 99.9%.
- Additional usable runner capacity must become available within 60 seconds.
- Runner instances and pods must use private networking and must not receive
  public IP addresses.
- Runner IAM roles must use the organization permissions boundary supplied to
  this module.
- The runner AMI must be resolved through the approved platform mechanism; do
  not hard-code an AMI ID.
- Existing infrastructure owned outside this repository must not be recreated,
  imported, deleted, or silently taken under management.

Repository/code changes and offline validation are authorized. External
infrastructure mutation, including `terraform apply`, is not authorized.

# Security requirements

- No runner instance or pod may be assigned a public IP address.
- Every IAM role created by this module must set the permissions boundary from
  `var.permissions_boundary_arn`.
- The approved AMI must be resolved indirectly from the platform-owned SSM
  parameter rather than copied to a literal AMI ID.
- Do not import, modify, or delete resources whose ownership is not established.

## Settled W2 node-role contract

The safe runner identity/image slice does not depend on W1 compute selection.
The runner-node role trust principal is exactly `ec2.amazonaws.com`. Attach the
following AWS-managed policies:

- `arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy`;
- `arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryPullOnly`; and
- `arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy`.

Set `permissions_boundary = var.permissions_boundary_arn`. Repository-local IAM
and SSM lookup implementation is authorized now; external apply is not.
